    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    dangerous_prev = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = float(prev['bid'])
                prev_bids.append(bid)
                if opp.get('budget', 0) >= bid * 0.8:
                    dangerous_prev.append(bid)

    if not alive:
        if hp <= 2 or no_water_days >= 1:
            return max(0.0, min(budget, 35.0))
        return max(0.0, min(budget, 8.0))

    high_pressure = max(prev_bids) if prev_bids else 0.0
    active_pressure = max(dangerous_prev) if dangerous_prev else high_pressure

    supply_tight = supply <= 17.0
    supply_loose = supply >= 22.0

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 2

    if supply_tight:
        urgency += 2
    elif supply <= 19.0:
        urgency += 1
    elif supply_loose:
        urgency -= 1

    if day >= 8:
        urgency += 1

    if budget <= 25:
        base = budget
    elif urgency <= 0:
        base = 6.0 if supply_loose else 10.0
    elif urgency == 1:
        base = 16.0 if supply_loose else 22.0
    elif urgency == 2:
        base = 28.0 if not supply_tight else 38.0
    elif urgency == 3:
        base = 45.0 if not supply_tight else 58.0
    else:
        base = 62.0 if not supply_tight else 70.0

    if active_pressure >= 180.0:
        if urgency >= 4:
            bid = max(base, min(72.0, active_pressure * 0.42))
        else:
            bid = min(base, 18.0)
    elif active_pressure >= 120.0:
        if urgency >= 3:
            bid = max(base, min(68.0, active_pressure * 0.48))
        else:
            bid = base
    elif active_pressure > 0.0:
        target = active_pressure + 2.0
        cap = 65.0 if urgency >= 3 else 48.0
        bid = max(base, min(target, cap))
    else:
        bid = base

    if budget > 140 and urgency >= 3:
        bid += 4.0
    if budget < 60:
        bid = min(bid, budget * 0.75 + 8.0)

    bid = max(0.0, min(budget, bid))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 # From Current Meta-Round State

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if num_alive_opponents == 0:
        return min(my_status['budget'], 1.0)

    bid_factor = 0.65

    if my_status['hp'] <= 2:
        bid_factor = 0.95
    elif my_status['no_water_days'] >= 1:
        bid_factor = 0.85
    elif my_status['hp'] <= 5:
        bid_factor = 0.75

    base_bid = DAILY_SALARY * bid_factor

    estimated_total_demand = WATER_REQ + sum(o['water_requirement'] for o in alive_opponents)

    if day_context['supply'] < estimated_total_demand * 0.7:
        base_bid *= 1.15
    elif day_context['supply'] > estimated_total_demand * 1.3:
        base_bid *= 0.9

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        if highest_prev_bid >= DAILY_SALARY * 0.8:
            if my_status['hp'] <= 5 or my_status['no_water_days'] >= 1:
                base_bid = max(base_bid, highest_prev_bid + (DAILY_SALARY * 0.05))
            else:
                base_bid = max(base_bid, highest_prev_bid * 0.95)
        elif highest_prev_bid < DAILY_SALARY * 0.5:
            base_bid = min(base_bid, highest_prev_bid + (DAILY_SALARY * 0.05))
            base_bid = max(base_bid, DAILY_SALARY * 0.4)

    final_bid = min(my_status['budget'], max(1.0, base_bid))

    if day_context['day'] >= EPISODE_DAYS - 2 and my_status['hp'] <= 3:
        final_bid = my_status['budget'] * 0.98

    return final_bid

